import{_ as t,o as a,c as r,a2 as o}from"./chunks/framework.BTLSZHNB.js";const p=JSON.parse('{"title":"Edge Platform Family proposals","description":"","frontmatter":{},"headers":[],"relativePath":"proposals/edge/index.md","filePath":"proposals/edge/index.md"}'),d={name:"proposals/edge/index.md"};function i(n,e,s,c,l,m){return a(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="edge-platform-family-proposals" tabindex="-1">Edge Platform Family proposals <a class="header-anchor" href="#edge-platform-family-proposals" aria-label="Permalink to &quot;Edge Platform Family proposals&quot;">​</a></h1><p>The Edge Platform Family, <code>edge.forms.takoform.com/v1alpha1</code>, is the first official Form Family (<a href="./../../spec/decisions/0009-form-families-and-namespaced-api-versions.html">decision 0009</a>). Its members fix, completely, the application-visible semantics of a proven edge developer platform without naming its vendor (<a href="./../../spec/decisions/0008-forms-preserve-service-shape.html">decision 0008</a>).</p><h2 id="authoring-policy-shape-preserving-contracts" tabindex="-1">Authoring policy: shape-preserving contracts <a class="header-anchor" href="#authoring-policy-shape-preserving-contracts" aria-label="Permalink to &quot;Authoring policy: shape-preserving contracts&quot;">​</a></h2><p>Every member Form preserves one service shape end to end: execution ABI, client API, data model, consistency, delivery guarantees, update and delete units, error semantics, and the capabilities exposed through typed Bindings. No free semantic token is admitted; a difference in semantics is a different Form, never a selector value. Outward capability use is a digest-bound Binding held by a revision resource; inward activation is an attachment resource (<a href="./../../spec/decisions/0010-exact-interface-and-binding-contracts.html">decision 0010</a>). Desired schemas carry no <code>name</code> or envelope plumbing: the v1alpha3 resource envelope owns identity and status (<a href="./../../spec/decisions/0011-resource-identity-generation-and-revision.html">decision 0011</a>).</p><p>The catalog source of truth is <code>internal/edgeformcatalog</code>; the generated candidates live in <code>forms/candidates/edge/v1alpha1</code>, the exact Interface and Binding candidates in <code>interfaces/candidates/v1alpha1</code> and <code>bindings/candidates/v1alpha1</code>.</p><h2 id="mvp-members" tabindex="-1">MVP members <a class="header-anchor" href="#mvp-members" aria-label="Permalink to &quot;MVP members&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Form</th><th>Role</th><th>One-line semantics</th><th>Separate-Form boundary</th></tr></thead><tbody><tr><td><a href="./module-worker.html">ModuleWorker</a></td><td>identity</td><td>Logical identity of one ES Module Worker application; the ABI is fixed by identity.</td><td>A WASI function or container service is a different Form.</td></tr><tr><td><a href="./worker-bundle.html">WorkerBundle</a></td><td>revision</td><td>Immutable content-addressed module bundle: main module plus digest-pinned modules.</td><td>A different linking or packaging model is a different Form.</td></tr><tr><td><a href="./worker-version.html">WorkerVersion</a></td><td>revision</td><td>Immutable executable snapshot: bundle, handlers, vars, sensitive slots, typed bindings.</td><td>Mutable in-place code or config is not a version of this Form.</td></tr><tr><td><a href="./worker-deployment.html">WorkerDeployment</a></td><td>deployment</td><td>Basis-point traffic split across up to eight Worker Versions of one worker.</td><td>Per-request routing rules or geographic steering is separate work.</td></tr><tr><td><a href="./worker-custom-domain.html">WorkerCustomDomain</a></td><td>attachment</td><td>Serves one DNS hostname from a worker&#39;s active deployment over HTTPS.</td><td>Path-pattern routes are a separate attachment Form.</td></tr><tr><td><a href="./worker-endpoint.html">WorkerEndpoint</a></td><td>attachment</td><td>Makes a worker reachable over HTTPS at an address the host assigns and publishes.</td><td>A name the author owns is <code>WorkerCustomDomain</code>; a chosen label or region is host placement, not a Form.</td></tr><tr><td><a href="./worker-cron-trigger.html">WorkerCronTrigger</a></td><td>attachment</td><td>Invokes the scheduled handler on a five-field UTC cron schedule.</td><td>Timezone-aware scheduling is a different Form.</td></tr><tr><td><a href="./edge-kv-namespace.html">EdgeKVNamespace</a></td><td>identity</td><td>Globally replicated key/value namespace with eventual consistency.</td><td>A linearizable or per-key-consistent store is a different Form.</td></tr><tr><td><a href="./object-bucket.html">ObjectBucket</a></td><td>identity</td><td>Flat-namespace object store with read-after-write consistency and strong etags.</td><td>CORS/lifecycle/lock rules are separate policy Forms.</td></tr><tr><td><a href="./sqlite-database.html">SQLiteDatabase</a></td><td>identity</td><td>Embedded SQLite database with serializable transactions.</td><td>A Postgres or MySQL database is a different Form.</td></tr><tr><td><a href="./at-least-once-queue.html">AtLeastOnceQueue</a></td><td>identity</td><td>Queue with at-least-once delivery and no ordering guarantee.</td><td>A FIFO or exactly-once queue is a different Form.</td></tr><tr><td><a href="./queue-consumer.html">QueueConsumer</a></td><td>attachment</td><td>Attaches one worker as the batch consumer of one queue, with retry and dead-lettering.</td><td>Pull-based consumption over an API is a different Form.</td></tr></tbody></table><p>Designs that differ in these semantics — <code>PostgresDatabase</code>, <code>FifoQueue</code>, <code>WasiFunction</code>, <code>ContainerService</code>, <code>TimezoneSchedule</code> — belong to future families and get their own proposals when that work starts, per <a href="./../../spec/form-families.html">spec/form-families.md</a>.</p>',8)])])}const f=t(d,[["render",i]]);export{p as __pageData,f as default};
